def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") != 1:
            return ""
        local, domain = value.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            value = f"{local}@{domain}"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""
        return value

    def normalize_phone(value):
        value = re.split(r"x|ext|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = "".join(ch for ch in value if ch.isdigit())
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        if "T" in value:
            return datetime.strptime(value, "%Y-%m-%dT%H:%M:%S")
        if "/" in value:
            return datetime.strptime(value, "%m/%d/%Y")
        return datetime.strptime(value, "%Y-%m-%d")

    def opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        updated = parse_updated(row["updated"])
        prepared.append({
            "index": index,
            "row": row,
            "email": email,
            "phone": phone,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "zip": normalize_zip(row["zip"]),
            "updated_dt": updated,
            "source": row["source"].strip().lower(),
            "opted_out": opted_out(row["opted_out"]),
            "tags": [
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            ],
        })

    # Build transitive groups with union-find.
    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_last_owner = {}
    for i, person in enumerate(prepared):
        if person["email"]:
            if person["email"] in email_owner:
                union(i, email_owner[person["email"]])
            else:
                email_owner[person["email"]] = i

        if person["phone"] and person["last_name"]:
            key = (person["phone"], person["last_name"].lower())
            if key in phone_last_owner:
                union(i, phone_last_owner[key])
            else:
                phone_last_owner[key] = i

    groups = {}
    for i, person in enumerate(prepared):
        groups.setdefault(find(i), []).append(person)

    def select_value(group, field, require_valid=False):
        candidates = [
            p for p in group
            if p[field] and (not require_valid or p[field])
        ]
        if not candidates:
            return ""
        chosen = min(
            candidates,
            key=lambda p: (
                p["source"] != "manual",
                -p["updated_dt"].timestamp(),
                p["index"],
            ),
        )
        return chosen[field]

    output = []
    ordered_groups = sorted(groups.values(), key=lambda group: min(p["index"] for p in group))
    for group in ordered_groups:
        latest = max(p["updated_dt"] for p in group)
        output.append({
            "first_name": select_value(group, "first_name"),
            "last_name": select_value(group, "last_name"),
            "zip": select_value(group, "zip"),
            "email": select_value(group, "email", require_valid=True),
            "phone": select_value(group, "phone", require_valid=True),
            "source": select_value(group, "source"),
            "tags": ";".join(sorted({tag for p in group for tag in p["tags"]})),
            "opted_out": "Y" if any(p["opted_out"] for p in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
